-- The API's reach into SECURITY DEFINER functions. Production's platform defaults grant EXECUTE on every
-- new public function to anon, authenticated and service_role, and this suite mirrors them
-- (platform-function-defaults.sql), so a function stays callable with the publishable key unless its
-- migration revokes those roles by name ("revoke ... from public" is not enough; 20260928279570 closed
-- 44 that relied on it). This is the reviewed list of every non-trigger SECURITY DEFINER function in
-- public that anon or authenticated may execute, with whether each role may, and why that is safe. It
-- runs first, against the migrations alone.
--
-- A new or changed function that anon or authenticated can execute fails this until it is listed here.
-- Before listing it: is it meant for members (in supabase/CLIENT-CONTRACT.md, and it checks the caller)
-- or does its body refuse every API caller? If neither, revoke it from anon and authenticated by name
-- (and from service_role when no service caller exists). A function the roles can no longer execute, or
-- that no longer exists, must leave the list too, so the list never grants ahead of time.
-- Generated 2026-09-29 from a production-posture build; "only through the platform default" marks a grant
-- that no migration made, which CI never had before the suite mirrored the defaults.
begin;
set local search_path = pg_catalog;

create temporary table api_function_allowlist(
	signature text primary key,
	anon boolean not null,
	authenticated boolean not null,
	reason text not null check (char_length(reason) > 0)
) on commit drop;


do $$
declare v_unknown text[]; v_unlisted text[]; v_changed text[]; v_stale text[];
begin
	select array_agg(signature order by signature) into v_unknown
	from pg_temp.api_function_allowlist where to_regprocedure(signature) is null;
	with exposed as (
		select p.oid, p.oid::regprocedure::text as signature,
			has_function_privilege('anon', p.oid, 'EXECUTE') as anon,
			has_function_privilege('authenticated', p.oid, 'EXECUTE') as authenticated
		from pg_proc as p
		where p.pronamespace = 'public'::regnamespace
			and p.prosecdef
			and p.prorettype not in ('trigger'::regtype, 'event_trigger'::regtype)
			and not exists (select 1 from pg_depend as d
				where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
			and (has_function_privilege('anon', p.oid, 'EXECUTE') or has_function_privilege('authenticated', p.oid, 'EXECUTE'))
	), listed as (
		select to_regprocedure(list.signature)::oid as oid, list.*
		from pg_temp.api_function_allowlist as list
		where to_regprocedure(list.signature) is not null
	)
	select
		array_agg(format('%s (anon %s, authenticated %s)', exposed.signature, exposed.anon::text, exposed.authenticated::text)
			order by exposed.signature) filter (where listed.oid is null),
		array_agg(format('%s (anon %s, authenticated %s; listed anon %s, authenticated %s)', exposed.signature,
			exposed.anon::text, exposed.authenticated::text, listed.anon::text, listed.authenticated::text) order by exposed.signature)
			filter (where listed.oid is not null and (listed.anon, listed.authenticated) <> (exposed.anon, exposed.authenticated)),
		array_agg(listed.signature order by listed.signature) filter (where exposed.oid is null)
	into v_unlisted, v_changed, v_stale
	from exposed full join listed on listed.oid = exposed.oid;
	v_stale := coalesce(v_unknown, '{}') || coalesce(v_stale, '{}');
	if v_unlisted is not null or v_changed is not null or cardinality(v_stale) > 0 then
		raise exception E'API functions differ from supabase/tests/001_api_function_allowlist.test.sql.\n'
			'Executable by anon or authenticated but not listed (new, or reopened by a grant or a re-create):\n  %\n'
			'Listed, but anon or authenticated can execute it differently from its row:\n  %\n'
			'Listed, but no longer executable by anon or authenticated, or no such function:\n  %',
			coalesce(array_to_string(v_unlisted, E'\n  '), 'none'),
			coalesce(array_to_string(v_changed, E'\n  '), 'none'),
			coalesce(nullif(array_to_string(v_stale, E'\n  '), ''), 'none')
			using hint = 'If the function is internal, revoke it by name in its migration: revoke all on function <signature> '
				'from public, anon, authenticated (and service_role when no service caller exists). "revoke ... from public" '
				'alone leaves the platform''s grants. Only a member or anon RPC that checks its caller belongs in the list: '
				'add or edit its row here with the reason (see the header). A revoke that closes a listed role edits its row too.';
	end if;
end
$$;

rollback;
